import { defaultConfig } from './default.js';
import { validateConfig } from './validator.js';

export function loadConfig() {
  const config = { ...defaultConfig };
  
  // 环境变量覆盖
  if (process.env.GET_NOTE_API_BASE_URL) {
    config.api.baseURL = process.env.GET_NOTE_API_BASE_URL;
  }
  
  if (process.env.GET_NOTE_API_TIMEOUT) {
    config.api.timeout = parseInt(process.env.GET_NOTE_API_TIMEOUT);
  }
  
  if (process.env.GET_NOTE_API_RETRIES) {
    config.api.retries = parseInt(process.env.GET_NOTE_API_RETRIES);
  }
  
  if (process.env.GET_NOTE_TOPIC_ID) {
    config.knowledgeBase.topicId = process.env.GET_NOTE_TOPIC_ID;
    config.knowledgeBase.topicIds = [process.env.GET_NOTE_TOPIC_ID];
  }
  
  // 验证配置
  validateConfig(config);
  
  return config;
}

export const config = loadConfig();